import{A as e,B as t,V as n,et as r}from"./chunks/framework.COrJTECx.js";var i=JSON.parse(`{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}`),a={name:`about.md`};function o(e,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[n(`<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to “About”">​</a></h1><p>Autossential is a suite of custom activities for <a href="https://www.uipath.com" target="_blank" rel="noreferrer">UiPath</a> that gives to developers practical, reusable building blocks that reduce boilerplate and repetitive coding patterns, helping automations stay cleaner and faster to build. The suite is organized into two independent packages: <strong>Autossential.Activities</strong> and <strong>Autossential.Workbook.Activities</strong>.</p><h2 id="autossential-activities" tabindex="-1">Autossential.Activities <a class="header-anchor" href="#autossential-activities" aria-label="Permalink to “Autossential.Activities”">​</a></h2><p>This package complements UiPath&#39;s native activity set with general-purpose activities organized into clear categories:</p><ul><li><strong>Data</strong> — utilities for working with DataTables and dictionaries, such as promoting headers, transposing data, removing empty rows, and updating dictionaries.</li><li><strong>Files</strong> — streamlined handling of files and folders, including cleanup, waiting for files, and zip/unzip operations.</li><li><strong>Programming</strong> — activities that reduce the need for custom code, such as culture scoping, token replacement, and data parsing/merging.</li><li><strong>System</strong> — helpers for drive mapping and process management.</li><li><strong>Workflow</strong> — control-flow activities that improve readability and simplify orchestration logic (conditionals, timed loops, checkpoints, and controlled exits).</li></ul><p>The package is compatible with both Windows and Cross-Platform UiPath projects, letting developers build more efficient workflows without falling back on custom code for common tasks.</p><h2 id="autossential-workbook-activities" tabindex="-1">Autossential.Workbook.Activities <a class="header-anchor" href="#autossential-workbook-activities" aria-label="Permalink to “Autossential.Workbook.Activities”">​</a></h2><p>This package focuses on Excel workbook manipulation without requiring Microsoft Excel to be installed, supporting both XLSX and XLS formats. It provides activities for:</p><ul><li>Reading and writing cells, ranges, and tables.</li><li>Working with formulas, including automatic evaluation of cached values.</li><li>Managing workbook structure — adding, editing, and formatting worksheets, controlling visibility, and configuring freeze panes.</li><li>Performing high-performance operations suitable for unattended automation, avoiding unnecessary I/O through change detection.</li></ul><p>Because it doesn&#39;t depend on Excel being installed, this package is well suited for server-side or unattended environments and large-scale data processing scenarios.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};